package br.com.equilibra.transaction.api;
import br.com.equilibra.transaction.application.TransactionHistoryService;import br.com.equilibra.transaction.domain.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import java.time.Instant;
@RestController @RequestMapping("/transactions") @Tag(name="Transaction history",description="Histórico unificado de transações") @SecurityRequirement(name="bearerAuth") public class TransactionHistoryController{private final TransactionHistoryService service;public TransactionHistoryController(TransactionHistoryService service){this.service=service;}@GetMapping public ResponseEntity<TransactionHistoryPageResponse> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(required=false)TransactionType type,@RequestParam(required=false)TransactionStatus status,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant from,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant to,@RequestParam(name="accountId",required=false)String accountId,@RequestParam(name="categoryId",required=false)String categoryId){return ResponseEntity.ok(service.list(page,size,type,status,from,to,accountId,categoryId));}}
